(function(){
  function filter(pathsText, pattern, opt){
    opt=opt||{};
    var paths=String(pathsText||'').split(/\r?\n/).map(function(s){return s.replace(/\r/,'');}).filter(function(s){return s.trim().length;});
    var mode=opt.mode||'regex', re=null;
    if(mode==='regex'){ try{ re=new RegExp(pattern, opt.ic?'i':''); }catch(e){ return {error:'正则错误: '+e.message}; } }
    var out=[];
    for(var i=0;i<paths.length;i++){ var p=paths[i], name=p.replace(/^.*[\\\/]/,''), hit=false;
      if(mode==='regex') hit=re.test(name);
      else if(mode==='substr') hit=name.toLowerCase().indexOf(pattern.toLowerCase())>=0;
      else if(mode==='exact') hit=name.toLowerCase()===pattern.toLowerCase();
      if(hit) out.push(p); }
    return {value:out};
  }
  var API={filter:filter};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__FdForge__=API;
})();
